import 'package:flutter/material.dart';
void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,home:const Tela());}
class Tela extends StatefulWidget{const Tela({super.key});@override State<Tela> createState()=>_TelaState();}
class _TelaState extends State<Tela>{final distancia=TextEditingController(),litros=TextEditingController();String resultado='';void calcular(){final d=double.tryParse(distancia.text.replaceAll(',','.')),l=double.tryParse(litros.text.replaceAll(',','.'));if(d==null||l==null||l<=0){setState(()=>resultado='Informe valores válidos e litros maiores que zero.');return;}final consumo=d/l;setState(()=>resultado='Consumo médio: ${consumo.toStringAsFixed(1)} km/l\nClassificação: ${consumo>=12?'Econômico':'Consumo elevado'}');}void limpar(){distancia.clear();litros.clear();setState(()=>resultado='');}@override void dispose(){distancia.dispose();litros.dispose();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Consumo de combustível')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:distancia,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Distância (km)')),TextField(controller:litros,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Combustível (litros)')),const SizedBox(height:20),Row(mainAxisAlignment:MainAxisAlignment.center,children:[ElevatedButton(onPressed:calcular,child:const Text('Calcular')),const SizedBox(width:12),ElevatedButton(onPressed:limpar,child:const Text('Limpar'))]),const SizedBox(height:24),Text(resultado)])));}
